(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sco"] = {"ui":{"skip":"Skip tae the content","back":"← Back tae AI-gile","lang.button":"Leid: {name}","lang.dialog":"Pick a leid","lang.search":"Seek leids","lang.none":"Nae leid matches","lang.notYet":"{name} isnae translatit yet","theme.aria":"Chynge theme: licht, dairk or black","theme.toLight":"Chynge tae the licht theme","theme.toDark":"Chynge tae the dairk theme","theme.toBlack":"Chynge tae the black theme (true black, easy on OLED screens)","words.underline":"Unnerline thir words on the page","words.underlineHelp":"Hover ower or tap a dottit word tae see whit it means.","words.col.todo":"Cairds pickit for nou: the team stairts on thir neist.","words.col.doing":"An AI is warkin on this caird the noo.","words.col.review":"Ae AI hass duin the wark; anither checks it afore it comes tae ye.","words.col.verify":"Waitin on ye: gie it a go an say if it warks.","words.col.team":"Yer notes or answers, waitin on the team tae pick them up.","words.col.done":"Duin an acceptit.","index.title":"AI-gile: yer AI dev team, on the ae board","index.description":"AI-gile is a kanban board for AI codin teams. They wirk while ye sleep; ye get the ae wee pile o things tae decide, test an accept.","hero.logoAlt":"AI-gile board icon","hero.h1.html":"Yer AI dev team, on the ae&nbsp;board.","hero.alpha":"🐣 Steekit pre-alpha","hero.alphaTitle":"Early an unfinished: thanks for tryin it!","hero.lede":"They big while ye sleep. Ye wauken tae the ae wee pile: a few questions, a few things tae test, a purple diamond or twa. Clap, accept, an back tae yer coffee.","dl.windows":"Windows app","dl.browser":"Rin it in yer browser","dl.messenger":"📱 Messenger for yer phone","dl.soon":"Comin soon","dl.notify":"🔔 Tell me when it opens","dl.notifySmall":"Alpha or beta","hero.secondary":"Agile, but the team niver needs a stand-up coffee. (They dae stand-ups onieweys.)","pitch.h2":"AI-gile in as mony words as ye like","pitch.lede":"Pick a length, frae the ae word tae 144. Ilka length is its ain description, scrievit for that size. Drag the slider or use the arrow keys.","pitch.rangeLabel":"Length in words","pitch.dice":"🎲 anither version","pitch.words.one":"{n} word","pitch.words.other":"{n} words","pitch.letters.one":"{n} letter","pitch.letters.other":"{n} letters","pitch.chars.one":"{n} character","pitch.chars.other":"{n} characters","count.line.html.one":"{n} caird on the board richt noo","count.line.html.other":"{n} cairds on the board richt noo","people.humans.html.one":"👥 {n} human","people.humans.html.other":"👥 {n} humans","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agents","people.working.html.one":"⚡ {n} at wark richt noo","people.working.html.other":"⚡ {n} at wark richt noo","pre.title":"AI-gile: somethin's bein biggit","pre.description":"Somethin's bein biggit here: a board whaur AI teams big whit ye ask for, an learn ye as they gang. Steekit pre-alpha wi pals for noo.","pre.h1":"Somethin's bein biggit here. 🤫","pre.line":"A board whaur AI teams big whit ye ask for, an learn ye as they gang. Steekit pre-alpha wi pals for noo.","pre.btn":"🔔 Tell me when it opens","pre.peek":"Ahint the gless: the real board, live. Ilka caird is a coloured baur.","pre.peekFake":"Ahint the gless: whit a board at wark looks like.","pre.night":"🌙 The nicht watchman's in chairge · 😴 the body's restin","features.aria":"Whit it dis","f.pile.h":"The ae pile for ye","f.pile.html":"<b>For ye</b> haulds awthing waitin on ye, athort ilka project: questions, things tae test, jobs only a body can dae. Yer queue tells ye whit's neist an hou lang it taks.","f.sleep.h":"Teams that wirk while ye sleep","f.sleep.p":"Ilka project haes a lead an a team o AI agents. Comment on a caird an the team wakes up, daes the wirk, an hauns it back wi steps a tired body can follae.","f.tester.h":"An AI tester checks first","f.tester.p":"Afore onything reaches ye, a tester follaes the steps in a copy o the app an shaws whit it saw, wi a screenshot. Flick thro the anes that passed an accept in a clap.","f.proof.h":"Proof, nae promises","f.proof.p":"Ilka haun-ower shaws whit chynged: the files, the diff, the screenshots. Nae openin ilka app tae see if it's duin.","f.chat.h":"Blether wi yer leads","f.chat.p":"A Discord-style rail: ae icon per project, purple diamonds for whit needs ye. Message a lead an idea; they turn it intae cairds an a plan, wi a ✅ Go button.","f.tidy.h":"Keeps itsel tidy","f.tidy.p":"Related cairds fauld intae ane, muddled titles get fixed, an a token check keeps the code lean. Fewer things tae flit atween, less tae think on.","f.private.h":"Yours, on yer computer","f.private.li1":"The board rins on yer ain machine an only answers tae ye.","f.private.li2":"Private DMs atween fowk are end-tae-end encryptit.","f.private.li3":"Nae accounts, nae trackers, nae cookies.","f.lang.h":"In yer ain leid","f.lang.p":"Ower 120 leids, frae Dutch, Welsh an Japanese tae pirate, Yoda an Klingon, wi a quick switch back tae English for the industry jargon.","f.service.h":"Fae an idea tae a real service","f.service.p":"Biggit somethin wi AI that fowk uise noo? Mark it as a service an the board helps ye rin it weel: uptime checks, a public status page, incidents wi a write-up, chynges that need a Go, backups checkit daily. Help learns ye ilka step as ye gang.","msgr.h2":"AI-gile Messenger: yer team in yer pooch","msgr.p1":"Blether wi yer AI team wioot openin the board. Chat wi yer project leads an yer pals, an see a caird's test steps an answer them, aw frae yer phone.","msgr.p2":"Tae pair it, scan a QR code on yer board. First time? A freendly demo chat shaws ye roond.","msgr.when":"Android first, syne a web version for phones an iPhone.","msgr.who":"Yer project lead","msgr.b1":"The dairk mode fix is ready. Want the test steps?","msgr.b2":"Aye, please!","msgr.b3":"1. Open Settins. 2. Pick Dairk. Dis it look richt?","tl.aria":"Timeline frae the first blether tae the roadmap","tl.h2":"Frae the first blether tae whit's neist","tl.lede":"Real dates an times, in yer ain time zone. Efter the day it's the plan, wi nae dates promised.","tl.today":"The day","tl.planned":"plannit","tl.doing":"gaun on","tl.cards.one":"{n} caird","tl.cards.other":"{n} cairds","join.h2":"Jyne in","join.lede":"AI-gile is bein biggit by a beardit weirdo wi AuDHD an a few mental health battles, an a hantle o patient agents. It's private for noo, in a steekit alpha wi freends. Fancy a shot when it opens up?","join.btn":"Register interest","join.small":"We'll email ye, naething else","footer.tag":"AI-gile. Nae trackers, nae cookies, nae stand-up coffee.","footer.licence":"Business licence","footer.status":"Status","footer.privacy":"Whit we keep","footer.thanks":"Calls thanks tae ChilledChat","form.sending":"Sendin…","form.failed":"That didnae wirk: try again later.","form.offline":"Couldnae reach AI-gile: try again later.","form.keep":"We only use this tae reply tae ye, then delete it. Nae trackers, nae cookies.","form.keepLink":"Whit we keep","interest.title":"AI-gile: tell me when the alpha opens","interest.description":"Leave yer email tae hear when AI-gile's steekit alpha or beta opens.","interest.h1":"🔔 Tell me when it opens","interest.lede":"AI-gile is in steekit pre-alpha. Leave yer email an we'll write the ae time, when there's a place for ye.","interest.email":"Yer email","interest.which":"Which test?","interest.alpha":"Steekit alpha: early, rouch, lots o chynges","interest.beta":"Beta: steadier, later","interest.both":"Either, whitever comes first","interest.submit":"Pit me on the list","interest.thanks":"Thanks! Ye're on the list.","licence.title":"AI-gile: business licence","licence.description":"Usin AI-gile in yer business? Apply for a free business licence.","licence.h1":"📜 Business licence","licence.lede":"Usin AI-gile at wirk? Tell us wha ye are an whit ye dae. If it daes some guid, the licence is free.","licence.company":"Company","licence.website":"Website","licence.what":"Whit ye dae","licence.how":"Hou it helps the warld","licence.email":"Email","licence.submit":"Apply","licence.thanks":"Thanks! We'll reply by email.","status.title":"AI-gile status","status.h1":"AI-gile status","status.quiet":"Aw quiet","status.intro":"Is AI-gile wirkin richt noo? This page checks the website, board sharin, calls an the download every 5 minutes.","status.up":"Wirkin (answert in {ms} ms)","status.slow":"Didnae answer the last check, tryin again","status.down":"Doon: didnae answer the last twa checks","status.svc.web":"Website","status.svc.web.offers":"This site: whit AI-gile is, an the interest form","status.svc.boards":"Board sharin","status.svc.boards.offers":"Public boards, messages atween freends an invites","status.svc.calls":"Calls","status.svc.calls.offers":"Voice, video an screen share in AI-gile","status.svc.download":"Download","status.svc.download.offers":"The Windows installer an invite links","status.checking":"Checkin…","status.offline":"Cannae reach the status service richt noo (tryin again)","status.updated":"updatit {ago}","status.justNow":"jist noo","status.min":"{n} min syne","status.hours":"{n} h syne","status.days":"{n} d syne","privacy.title":"AI-gile: whit we keep","privacy.h1":"Whit we keep","privacy.lede":"Short version: only whit ye send us, an no for lang.","privacy.only":"Only whit ye send us: whit ye type intae a form, like yer email. Naethin else aboot ye.","privacy.sealed":"It's sealt sae oor server cannae read it: in yer browser afore it leaves (on an aulder browser, the meenit it arrives). Only oor ain board can open it.","privacy.server":"It's deletit fae the server as soon as it reaches oor board. Onythin still there efter 30 days is deletit onywey.","privacy.board":"We keep it on oor board only till we've replied tae ye, then delete it there an aw.","privacy.none":"Nae trackers, nae cookies, nae analytics.","privacy.local":"Yer leid an yer licht or dark choice bide in yer ain browser. They're never sent tae us.","privacy.ask":"Want it gane sooner? Reply tae oor email an say sae.","live.h2":"Watch it bein biggit, live","live.caption":"Ilka caird is hid: ye see the shape o the wark, no the words.","live.watching.one":"live: {n} watchin","live.watching.other":"live: {n} watchin","live.last.now":"Last caird moved jist noo","live.last.min.one":"Last caird moved {n} min syne","live.last.min.other":"Last caird moved {n} min syne","live.last.hour.one":"Last caird moved {n} oor syne","live.last.hour.other":"Last caird moved {n} oors syne","live.last.day.one":"Last caird moved {n} day syne","live.last.day.other":"Last caird moved {n} days syne","live.offline":"The live board's takkin a wee breather. Come back suin.","live.cols":"Backlog|Tae dae|Gaun on|Team checkin|For ye tae test|For the team|Duin"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Haundit."]},{"n":2,"texts":["Robot kanban.","Agents, sortit.","Ideas, biggit."]},{"n":3,"texts":["Kanban for robots.","Ideas become features.","Free agent kanban."]},{"n":5,"texts":["A kanban board rin by agents.","Ye write cairds. Agents big.","Free, local, tested, gey daft."]},{"n":8,"texts":["A free kanban board whaur AI agents wirk.","Write an idea. Agents big it. Ye accept.","Agile for the ae body an mony patient robots."]},{"n":13,"texts":["A kanban board on yer computer whaur AI agents tak up the cairds.","Write an idea. A team o agents bigs it. A tester checks it.","Free, nae accounts, nae trackers: a board, some robots, an ye in chairge."]},{"n":21,"texts":["AI-gile is a kanban board for wirkin wi AI codin agents. They tak up the cairds; ye test an accept them, an that's the lot.","Ilka project gets a lead an a team o AI agents. Comment on onie caird an the team gets stuck in tae the wirk.","A free, personal tae-dae board that rins on yer ain computer. The wirkers are robots. The ane that says aye is you."]},{"n":34,"texts":["Ye pit ideas on a board. A team o AI agents turns them intae wirkin features, tests them, an hauns them back wi steps tae try. Naething coonts as duin until ye say sae yersel.","AI-gile is a hamemade kanban board that Rich biggit wi a guid wheen o help frae the agents it noo manages. It's free, rins on yer computer, an is shared wi freends, nae sauld.","Picture an ordinar kanban board, wi columns frae Backlog tae Duin, except the cairds are ta'en up by AI agents. They report hou they're gettin on, ask questions when stuck, an aye wait on yer thumbs up."]},{"n":55,"texts":["AI-gile is a kanban board whaur the team is made o AI agents. Ilka project haes a lead that plans the wirk an helpers that big it. When a feature is ready, an AI tester tries it oot an taks a screenshot, then it lands in yer pile. Accept it, or leave a comment an they rewirk it.","It started oot as ae body's wey o keepin track o lots o AI codin sessions at aince, an grew intae a richt board. It rins on yer machine, needs nae account, an haes nae trackers. It's free for freends an onybody that's curious. It's alsae unfinished, sae expect some rouch edges an the odd surprise.","Here's the honest version. Ye still hae tae hae the ideas, an ye still hae tae check the results. Whit AI-gile daes is awthing in atween: it keeps the cairds in order, wakes the richt agent when ye comment, shaws exactly whit chynged, an keeps the lot in the ae short pile for ye."]},{"n":89,"texts":["AI-gile is a free kanban board that ye rin on yer ain computer. Insteid o fowk, ilka project haes a team o AI agents: a lead that turns yer ideas intae cairds an a plan, an helpers that tak up the cairds in priority order. When somethin is biggit, an AI tester follaes the test steps an shaws ye whit it saw. Then it waits in the ae pile merked For ye. Ye accept it, or ye comment an the team haes anither go. Naething iver reaches Duin wioot ye.","A wheen o things ye micht nae expect. A nicht watch keeps the Tae dae column topped up while ye sleep, pickin cairds that dinnae need an answer frae ye. A token coonter shaws hou muckle the agents hae uised the day an this week, an Nae Token Mode tells them tae stop spendin. Ye can message freends, an private messages are end-tae-end encryptit. The board speaks aboot 120 leids, includin Dutch, Flemish, pirate an Klingon. Nane o it costs a penny, an naebody's tryin tae sell it tae ye either.","AI-gile is a wee personal project, nae a company. Rich wantit tae look efter several AI codin projects wioot openin ilka app tae check on them, sae he an the agents biggit a board for it, then uised the board tae big the rest o itsel. It's in steekit pre-alpha, which means it wirks, mair or less, for a haunfu o freends. There's nae pricin page, nae newsletter an nae growth plan. If it sounds uisefu, ye can ask tae try it when it opens up a wee bit mair."]},{"n":144,"texts":["AI-gile is a kanban board for the ae human an a guid wheen o AI agents. It rins on yer ain computer an it's completely free. Ye add projects, an ilka project gets a lead an a wee team. Ye blether wi the lead, a bit like Discord, an describe an idea; the lead turns it intae cairds an a plan, then waits for ye tae chap Go. The team wirks thro the cairds in priority order, uisin a simple command line made for leid models. Afore onything comes back tae ye, an AI tester follaes the steps in a copy o the app an attaches a screenshot. Finished wirk lands in yer pile wi the chynged files an the diff. Ye accept it, or ye leave a comment an the team wakes up an tries again. Only ye can muive a caird tae Duin.","A day wi AI-gile, mair or less. In the evenin ye leave a few comments: this button's in the wrang place, that list should be sortit, could we hae a dairk mode. Ye gang tae yer bed. The agents read the comments, mak the chynges, test them an hand them back tae ye. If Tae dae rins dry, the nicht watch fills it frae the backlog wi cairds that need nae answer frae ye. In the mornin there's the ae short pile: a couple o questions an a few things tae try, ilk wi steps a sleepy body can follae an a screenshot o it wirkin. Ye click thro, accept the guid anes an send back the rest. A token coonter shaws whit it aw uised, an Nae Token Mode is there for lean weeks. Then ye hae yer breakfast, which the agents canna help wi yet.","First, whit AI-gile isnae. It isnae a startup, it isnae for sale, an naebody's collectin yer data. It's a free board that rins on yer computer, wi nae accounts, nae trackers an nae cookies. Whit it is: the ae tidy place tae see ilka AI codin project at aince, wi a team o agents daein the cairds an you makin the decisions. It faulds related cairds thegither, fixes muddled titles, an keeps an ee on hou lean the code bides. It speaks aboot 120 leids, frae Dutch an Flemish tae pirate an Klingon. Freends can message ilk ither, privately an encryptit. It wis biggit by Rich an a guid wheen o patient agents, mostly uisin itsel. It's in steekit pre-alpha, sae it's rouch in places. If it sounds like fun, ask nicely an ye micht get in early."]}],"quips":{"1":"The ae word. Bold. Maybe ower bold.","3":"Three words. Awready mair honest than maist product pages.","8":"Echt words. Still shorter than a stand-up.","21":"The lengths are story points, by the wey. O course they are.","55":"Fifty-five words. Twa cairds got finished while ye read that.","144":"That's the lang ane. There's nae 233. The agents hae gaen tae bed."}},"timeline":{"first-idea.name":"The first idea","first-idea.line":"The vera first blether, afore there wis ony code.","first-board.name":"First board","first-board.line":"A board that keeps track o its ain biggin: cairds, columns, drag an drap, projects.","team-roles.name":"Team an roles","team-roles.line":"Agent profiles, team templates, spaces an wha daes whit.","install.name":"Install an releases","install.line":"A zip a freend can install, self-updates, channels an rowin back.","usage-saver.name":"Usage saver","usage-saver.line":"Mizzer whit runs cost, keep the code lean, save yer limit.","friends.name":"Freends an sharin","friends.line":"Private DMs, a scrambled relay, invites, roles an shared projects.","languages.name":"Leids","languages.line":"Ilka screen text in a leid file, wi Dutch an Flemish first.","ai-tester.name":"AI tester","ai-tester.line":"A tester checks ilka haun-ower first an shaws whit it saw.","website.name":"The website","website.line":"aigile.lol, the teaser an this timeline.","streaming.name":"Chat an streamin","streaming.line":"Discord, Twitch, OBS, streamer mode, GIFs an emojis.","no-ai.name":"Nae AI edition","no-ai.line":"A board for fowk that code wioot AI, an public boards.","night-watch.name":"Nicht watch","night-watch.line":"A watchman an Scrum Master keep the teams on task while ye sleep.","p-more.name":"Awthing else","p-more.line":"Wee ideas still waitin their turn.","p-android.name":"Phone an Android","p-android.line":"Reach yer board frae a phone, then a native Android app.","p-release.name":"Alpha an ayont","p-release.line":"Steekit alpha, the live site, then beta.","p-languages.name":"Mair leids","p-languages.line":"130 leids, an an immersion mode fer learners.","p-engines.name":"Mair AI engines","p-engines.line":"Pick Claude, Codex, Gemini, Copilot or Cursor fer ilka agent.","p-pro.name":"Pro practice","p-pro.line":"Risk labels, merge gates, incident cairds an guard rails.","p-self.name":"Lookin efter ye","p-self.line":"Tired mode, self-care reminders an 4:20.","p-servers.name":"Servers an scale","p-servers.line":"Global server settings, roles an plannin for growth.","p-livestream.name":"Streamin extras","p-livestream.line":"Twitch chat, custom emojis an a public live view."},"words":{"button":"📖 Industry jargon","h":"📖 Wirds explained","intro":"Free trainin in plain leid: ilka wird ye meet frae a first idea tae a service fowk rely on, wi Agile, biggin, keepin it safe an warkin wi AI alang the wey.","search":"Seirch a word…","none":"Nae word matches that.","close":"Close","count":{"one":"{count} wird","other":"{count} wirds"},"groups":[{"id":"idea","name":"💡 Ideas an findin oot"},{"id":"plan","name":"🗺️ Plannin the wark"},{"id":"agile","name":"🔁 Agile weys o warkin"},{"id":"build","name":"🛠️ Biggin it"},{"id":"test","name":"🧪 Testin an quality"},{"id":"change","name":"🔀 Chyngin it safe"},{"id":"run","name":"🛎️ Rinnin a service"},{"id":"sec","name":"🔒 Security an privacy"},{"id":"ai","name":"🤖 Warkin wi AI"},{"id":"money","name":"💰 Siller an licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage o findin oot whilk problem's worth solvin an for wha, afore onythin gets biggit.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"Ane or twa sentences sayin wha has a problem, whit it is an why it matters, sae ilkane aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A body that uises whit ye build. Their needs are whit the wark is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Onybody that cares hou the wark turns oot or is affectit by it, like the fowk peyin for it, uisin it or supportin it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but lifelike body that staunds for ae kind o user, sae the team can spier “wad Sam fin this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Speakin tae an watchin real fowk tae lairn whit they need, raither than guessin.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a body taks tae get somethin duin, frae first hearin aboot it tae feenishin, an aa ootside yer product. Drawin it oot shaws whaur they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Somethin that annoys or slaws fowk doun the day. Guid products tak pain points awa.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Somethin ye believe but hinnae checked yet. Writin assumptions doun shaws whit tae test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess ye plan tae check, wi whit ye expect tae happen, like “fowk'll sign up if the first month's free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A wee planned test tae lairn if an idea warks, afore ye bet a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof o concept (PoC)","text":"A quick rough try tae see if an idea can wark at aa. It's usually thrawn awa aince ye hae the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model o the product, aften clickable pictures, tae try the idea on fowk afore biggin it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch o a screen shawin whaur things gae, wioot colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed pictur o hou a screen'll look, wi real colours an text, but nocht warks yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for daein a project: whit it costs, whit it brings in or saves, an the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether somethin can really be biggit an lookit efter wi the time, siller an skills ye hae."},{"id":"outcome","g":"idea","word":"Outcome","text":"The chynge ye want for fowk, like fewer missed appointments. It matters mair than hou muckle ye build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Somethin the team maks, like a new screen or a report. Makin it disnae automatically mean it helps onybody.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A nummer that tells ye if the wark did whit it wis for, like mair fowk feenishin their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important nummer ye watch tae see if things are gaun weel, like sign-ups a week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives an key results (OKRs)","text":"A wey o settin goals: the objective says whit ye want, an a wheen key results are the nummers that shaw ye got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing bein biggit an lookit efter for its users, sic as an app, a wabsite or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement o wha the product helps an whaur it's heidin in the lang run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The body that decides whit gets biggit an in whit order, sae the team aye warks on whit matters maist. In AI-gile that's you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The body that looks efter a product's direction: whilk problems it solves, for wha an why. PM can an aa mean project manager, sae check whilk.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The body that keeps a project on time an on budget, trackin wha daes whit an by whan.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan o whit's comin ower the next months, in order. It shaws direction, no exact dates, an chynges as ye lairn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A pynt in a project worth markin, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smaaest version o a product that's still uisefu tae real fowk, sae ye can lairn frae them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Somethin the feenished product maun dae or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"Whit's includit in the wark an, jist as important, whit's no.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"Whan mair an mair gets addit tae the wark bit by bit, wioot onybody agreein the extra time or cost, sae it niver quite feenishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"Ae thing the product can dae for fowk, like “reset yer passwird”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A muckle bit o wark, ower big for ae go, sae it's split intae smaaer cairds.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A wee bit o wark written frae the user's side: “As a shopper, I want tae save my basket, sae I can feenish later.” It stairts a blether aboot whit tae build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks ae caird maun pass tae coont as duin, agreed afore wark stairts, like “the basket's still there efter I log oot an back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job tae be duin, aften ae wee step o a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Anither wird for a caird: ae bit o wark or ae request, trackit frae stert tae feenish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"Hou important or urgent somethin is compared wi aathin else, sae the maist important wark gaes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Pittin wark in order o importance. A common wey is MoSCoW: Must have, Should have, Could have, Won't have this time.","also":["MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at hou big or hou lang a bit o wark is. It's a guess, no a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A wey o guessin the size o wark by comparin cairds wi ilk ither (“aboot twice as big as that ane”) raither than in oors. They're no for comparin teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessin the size o wark as S, M, L or XL. Quick an guid eneuch for early plannin.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A gemm for estimatin: ilkane shaws a size caird at the same time, then the heichest an laichest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"Whan ae bit o wark cannae stert or feenish till anither does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Onythin stoppin wark frae muivin forrit richt noo, like a missin answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date somethin maun be feenished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Somethin concrete the wark produces an hauns ower, like a warkin page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction o whit's likely tae happen, like whan the wark'll be duin, based on whit ye ken sae far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Onythin ye measure an track ower time, like page visits or hou lang a fix taks.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"Whit fowk tell ye aboot yer wark, guid an bad. Gettin it early an aften is the hert o Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"The waitin list o ideas an wark no plannit in yet, wi the maist important at the tap. Nocht there gets warked on till it muives tae Tae dae."},{"id":"sprint","g":"agile","word":"Sprint","text":"A short, fixed stretch o wark (aften ane or twa weeks, niver mair than a month) wi a goal an an agreed set o cairds tae feenish.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"A quick daily check-in: whit ilka team member did, whit they dae next, an whit's stoppin them. In Scrum it's caad the daily scrum.","also":["standup","stand-ups","daily scrum","daily stand-up"]},{"id":"kanban","g":"agile","word":"Kanban","text":"A wey o warkin whaur cairds muive across a board's columns (like Tae dae, Gaun on, Duin) an the team limits hou muckle is in progress at aince, sae wark keeps flowin."},{"id":"wip","g":"agile","word":"WIP limit","text":"WIP is short for wark in progress. A WIP limit is the maist cairds a column should hauld at aince, sae the team feenishes things afore stertin mair.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition o Duin","text":"The team's short checklist o whit “feenished” means, like testit an explained, afore a caird is haundit tae ye. Its twin, the Definition o Ready, says when a caird is clear eneuch tae stert.","also":["Definition of Ready","DoD","DoR"]},{"id":"retro","g":"agile","word":"Retro","text":"A regular look back at hou the team warks, tae agree on ane or twa things tae dae better next time. Short for retrospective. In AI-gile a retro suggests a chynge tae the team's weys o warkin, an ye say Go or No yet.","also":["retros","retrospective","retrospectives"]},{"id":"swarm","g":"agile","word":"Swarm","text":"Aa haunds on deck: mony fowk drap ither wark tae fix ae urgent thing thegither till it's sortit. In AI-gile ilka team helps on ae project, an ither projects wait the while.","also":["swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"In Scrum, the body that helps the team wark weel: clears whit blocks them, keeps meetins on track an coaches guid habits, wioot bossin onybody. In AI-gile the Lead Scrum Master spots stuck cairds, nudges the teams an minds ye o whit's waitin, across ilka project.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"A wey o warkin in wee steps: build a wee bit, shaw real results aften, lairn frae whit fowk say an chynge the plan as ye gae, raither than plannin aathin afore ye stert.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makkers. It pits fowk, warkin results, close wark wi customers an respondin tae chynge afore hivvy plans an paperwark.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The aulder wey o warkin: plan aathin, then build it aa, then test it aa, ae stage efter anither. Chynges late on are hard an costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"Ae roond o biggin somethin, checkin it an improvin it. Agile wark is a chain o thir, an a sprint is ae kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new warkin bit addit tae the product in a sprint or roond o wark, that fits wi whit wis there afore.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile wey o warkin: a wee team warks in short sprints towards a goal, wi set roles an a wheen regular meetins tae plan, check an improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The wee group that daes the wark in Scrum: a product owner, a Scrum Master an the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetins in Scrum: sprint plannin, the daily scrum, the sprint review an the retro. Mony fowk caa them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meetin at the stert o a sprint whaur the team agrees why the sprint matters, whilk cairds tae tak on an hou tae stert.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"Ae sentence sayin whit a sprint is for. Wee tasks can chynge alang the wey, sae lang as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cairds pickit for the current sprint, wi the team's plan for daein them.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The hail ordered list o aathin that micht be biggit for the product, maist important at the tap. It keeps chynging as ye lairn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is warkin towards, that helps the team choose whit tae dae next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly gaun throu the backlog tae tidy, split, order an add detail tae cairds, sae they're ready tae pick up. Caad backlog grooming an aa.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meetin at the end o a sprint whaur the team shaws whit it feenished an hears whit fowk think, tae decide whit comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Shawin feenished wark warkin, live, tae the fowk that speired for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amoont o time for somethin. Whan it rins oot ye stop, even if no aathin's duin.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"Hou muckle wark a team usually feenishes in a sprint, uised tae plan hou muckle tae tak on next time. It's no a score for hou hard fowk wark.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"Hou muckle wark the team can tak on in a period, efter holidays an ither jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart o the wark left in a sprint gaun doun day by day. If the line bides flat, somethin's stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart o feenished wark gaun up ower time, nixt tae the total plannit, sae ye can see whan ye'll get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itsel: a column for ilka stage o the wark, wi cairds muivin across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A wey o warkin whaur new wark only stairts whan somebody has room tae tak it on, raither than bein pushed on tae a fu plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"Hou smooth wark muives across the board. Guid flow means cairds keep muivin raither than pilin up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"Hou lang it taks frae somebody speirin for somethin tae it bein feenished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"Hou lang a caird taks frae whan wark really stairts on it tae whan it's feenished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"Hou mony cairds get feenished in a week, or in ony set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The ae stage whaur wark piles up an slaws aathin ahin it, like the narrae neck o a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A raw across the board that groups cairds o ae kind, sic as urgent wark or ae team's cairds.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A wey o warkin that cuts oot waste (onythin that disnae help the customer) an keeps wark flowin."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, onythin that taks effort but disnae help the customer, like waitin, rework or biggin things naebody uises.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Gettin a wee bit better aa the time throu wee regular chynges, then checkin they helped. Retros are ae wey tae dae it. Caad kaizen an aa.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itsel hou tae dae the wark, raither than bein telt step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has aa the skills it needs tae feenish the wark itsel, like design, biggin an testin.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit o research tae answer a question afore committin tae the real wark.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Daein wark again cause it wisnae richt the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Weys o uisin Agile across mony teams in a big organisation. SAFe (the Scaled Agile Framework) is ae weel kent example.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"The project's folder o code wi its fu history o commits. It can live on yer computer, on GitHub, or baith.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"A separate line o wark in the code, sae chynges can be made wioot touchin the main version.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"A saved snapshot o the code, wi a short note o whit chynged. Ye can aye gang back tae ane.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Sendin yer saved snapshots (commits) frae this computer tae the shared copy online, sic as GitHub, sae they're backed up an ithers can get them."},{"id":"merge","g":"build","word":"Merge","text":"Jynin the chynges frae ae branch intae anither, usually back intae the main version."},{"id":"pr","g":"build","word":"Pull request","text":"Askin for a branch's chynges tae be checkit an merged intae the main version. Some sites caa it a merge request.","also":["PR","PRs","merge request"]},{"id":"refactor","g":"build","word":"Refactor","text":"Tidyin the code wioot chyngin whit it dis: smaller files, clearer names, less repetition."},{"id":"bug","g":"build","word":"Bug","text":"Somethin that disnae wark the wey it should.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Peer review","text":"A second pair o een: somebody ither than the author checks the wark afore it reaches ye, sae fewer mistaks get throu. In AI-gile anither AI checks ilka caird.","also":["code review"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer whit tae dae. Caad source code an aa.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A leid for writin code, sic as JavaScript, Python or Java. Different anes suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Somebody that writes an chynges code. Caad a programmer or software engineer an aa.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that rin on computers an phones, as opposed tae the machines themsels (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program fowk uise tae get somethin duin, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that rins in a web browser, sae there's nocht tae install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The pairt o an app ye see an click on: the screens, buttons an wirds, aften in yer browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The ahin-the-scenes pairt o an app that keeps the data an daes the wark whan ye click somethin, like checkin yer passwird.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Warkin on baith the front end an the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"Whit a body sees an uises on screen: layoot, buttons, menus an text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"Hou it feels tae uise somethin: easy, clear an pleasant, or confusin an slaw.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Makkin things uisable by aabody, includin fowk that cannae see weel, cannae uise a moose or uise a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Makkin pages fit an wark weel on ony screen size, frae a phone tae a big monitor."},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit o colours, fonts, buttons an rules, sae ilka screen looks an behaves the same wey.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The owerall shape o a system: whit the main pairts are an hou they talk tae ilk ither."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store o information, like a gey pooerfu spreadsheet that the app can read an chynge.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layoot o a database: whilk tables o information it has an whit gaes in ilka ane.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the leid uised tae spier at mony databases for information or tae chynge it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settins.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that's aye on an answers requests frae ither computers, like sendin a web page whan ye visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that speirs for somethin, usually yer browser or app, speakin tae a server. In business it can jist mean a customer an aa.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu o requests ae program can mak o anither, like speirin at a weather service for the day's forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"Ae item on an API's menu: a web address a program can caa tae get or send somethin.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connectin twa systems sae they wark thegither, like yer shop sendin orders tae yer accoonts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message ae system sends tae anither by itsel the meenit somethin happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code somebody else wrate that ye can reuise instead o writin it yersel.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for biggin an app that decides muckle o hou the code is laid oot, like a hoose frame ye fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A kist o tools, code an examples for biggin software for ae platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool yer code needs tae wark. Keepin them up tae date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle o ready-made code ye can install an uise in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches an updates the packages yer code depends on. npm is a common ane.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The maist widely uised tool for keepin the history o code chynges, as commits an branches."},{"id":"github","g":"build","word":"GitHub","text":"A wabsite that keeps Git repos online, sae teams can share code, review chynges an track wark."},{"id":"vcs","g":"build","word":"Version control","text":"Keepin a fu history o ilka chynge tae the files, sae ye can see wha chynged whit an gae back if needit. Git daes this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Makkin yer ain fu copy o a repo, wi its history, on yer computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetchin the latest commits frae the shared copy (like GitHub) on tae yer computer. The opposite o push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version o the code that aabody warks frae, aften caad main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"Whan twa chynges touch the same lines in different weys, sae the computer cannae jyne them an a body has tae choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view shawin exactly whit chynged atween twa versions: lines addit an lines taen awa.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Yer ain copy o somebody else's repo, that ye can chynge wioot affectin theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that daes ae job by itsel, like tidyin files or stairtin the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turnin the code intae somethin ready tae rin, or the ready-tae-rin result itsel.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translatin code fowk wrate intae a form the computer can rin directly.","also":["compiler"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text windae whaur ye type instructions for the computer instead o clickin. Caad the terminal an aa.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settins that control hou software behaves, kept apairt frae the code sae they're easy tae chynge.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A settin haundit tae a program whan it stairts, aften uised for addresses or passwirds sae they're no written intae the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Huntin doun why somethin isnae warkin, an fixin it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Twa fowk (or a body an an AI) warkin on the same code thegither, ane typin an ane checkin.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations o hou somethin warks or hou tae uise it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file tae read in a repo: whit the project is an hou tae get it rinnin.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An aulder system still in uise that's hard tae chynge, aften cause few fowk still unnerstaun it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time noo but mak later chynges slawer, like a loan that gaithers interest. Refactorin pays it doun.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"A check that somethin warks the wey it should. Some tests the computer rins by itsel ilka time the code chynges; ithers are you tryin a feenished caird afore ye accept it.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Short for quality assurance: aathin duin tae mak shair wark is richt afore it gaes live. In AI-gile that means the automatic checks: whan QA is reid, somethin failed, an it cannae gae live till that's fixed.","also":["quality checks","quality assurance"]},{"id":"testpile","g":"test","word":"Test pile","text":"The feenished cairds waitin fer ye tae try, ane efter anither. Accept ane or send it back wi a note, an the next ane comes up.","also":["test piles"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer rins by itsel ilka time the code chynges, tae catch mistaks early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A body tryin the wark by haund tae see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A wee automatic check o ae tiny bit o code on its ain.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that a wheen pairts wark richt thegither, no jist ane at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user frae stert tae feenish, sic as signin up, buyin an peyin.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The fowk that speired for the wark try it themsels an say if it daes whit they need. AI-gile's test pile is its version o this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Somethin that uised tae wark but broke efter a chynge. Regression tests check that the auld things still wark.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A gey quick check that the main things wark at aa, for example richt efter a chynge gaes live. If it fails, stop an hae a look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Tryin the product freely an pokin at it in different weys, tae fin problems that plannit checks wad miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"Ae written scenario tae try: the steps, an whit should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"Hou muckle o the code is checked by automatic tests. Mair is usually safer, but heich coverage alane disnae prove it warks weel.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information uised while testin, sae naebody's real private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unco situation at the limits, like a tuim form or a name wi an apostrophe, whaur things aften brek.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route whaur aathin gaes richt. Guid testin tries the unhappy paths an aa."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checkin hou fast somethin is an hou weel it copes unner strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checkin hou a system copes whan lots o fowk uise it at aince.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Lookin for weaknesses that could let somebody misuise a system or see whit they shouldnae.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checkin that fowk wi different abilities can uise the product, includin wi a screen reader or jist a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistaks an messy style in code, like a spellin checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checkin code for problems by readin it automatically, wioot rinnin it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that whiles passes an whiles fails for nae clear reason, sae it cannae be fully trustit.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Makkin a bug happen again on purpose by follaein the same steps, sae it can be studied an fixed. Writin thae steps doun is the maist uisefu pairt o a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"Hou bad a problem's effect is, frae a wee annoyance tae aathin stoppin.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Copyin a new version o the software on tae the computers that rin it, sic as a test copy or the live service."},{"id":"release","g":"change","word":"Release","text":"A named bundle o feenished wark that gaes live thegither, wi short notes on whit chynged. 🚀 Releases writes the notes fae the duin cairds.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Gaun back tae the last version that warked whan a new ane causes trouble. In AI-gile, Roll back gethers the undo steps written on ilka chynge intae ae checklist.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that fowk uise, no a copy fer tryin things oot. Developers cry it production an aw.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Chynge","text":"A planned chynge tae somethin fowk rely on, written doon first: whit, how come, the risk, when, an how tae undae it. Stert ane wi 🔀 Raise a chynge.","also":["change","chynges","change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Somethin that could gang wrang, scored on how likely an how bad it wid be. ⚠️ Risks keeps them in ae list, heichest score first, ilk ane wi a date tae look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Chynge windae","text":"The times when chynges may gang live, like a quiet Tuesday nicht. Ootside a windae a chynge caird cannae be feenished, unless it's an emergency.","also":["chynge windaes","change window","change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A last check jist afore a chynge gaes live: ilka body that has tae approve says Go or No go. It only gaes ahead whan aabody says Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waitin on an aye afore wark sterts. A caird a pal raises, or a chynge, waits in ✅ Approvals till ye approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch o time, like durin a live stream, a demo or owernicht, whan nocht gaes live. The teams keep warkin an testin, but gaun live waits till it ends. Elsewhaur it's caad a change freeze.","also":["quiet times","chynge freeze","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"A wey o warkin whaur the fowk that build software an the fowk that rin it wark as ae team, wi lots o automation, sae chynges gae live aften an safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration an delivery)","text":"Aabody's chynges are jyned intae the main version aften an checked automatically ilka time (continuous integration), sae the software's aye ready tae gae live at the press o a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"Ae step further than continuous delivery: ilka chynge that passes the checks gaes live by itsel, wi nae button tae press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series o steps a chynge gaes throu on its wey tae live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"Ae separate copy o the system for ae purpose, sic as ane tae build in, ane tae test in an the live ane.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer warks in, aften on their ain computer, whaur brekkin things harms naebody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy o the system uised jist for testin, sae the real service isnae touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up jist like live, for a final check afore a chynge gaes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready tae be storit, checkit or pit live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix pit live quick, ootside the normal plan, cause somethin important's broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A wee update that fixes a bug or shuts a security hole. Applyin security patches quick matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says whilk release ye hae. Aften the first nummer chynges for big chynges an the last for wee fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list o whit chynged in a release, for the fowk that uise it, includin fixes an kent limits. Caad a changelog an aa.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on an aff switch for a feature, sae new wark can gae live hidden an be turned on (or aff again) wioot a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixin a bad release by quickly pittin oot a new, correctit version instead o gaun back tae the auld ane.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Pittin a chynge live for a wee group first, an for aabody only aince it looks fine. Named efter the canaries miners took unnergrund as an early warnin.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keepin twa copies o the live system an switchin fowk ower tae the new ane in ae go, sae ye can switch straucht back if it gaes wrang.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Pittin a new version live wioot the service iver stoppin for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helpin chynges succeed: weighin the risk, gettin the richt approval an pickin a guid time. Caad change management an aa.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks ower important chynges an agrees whether an whan they can gae ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A law-risk chynge duin the same tried an testit wey ilka time, sae it's approvit in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A chynge that needs checkit an approvit afore it gaes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A chynge that maun happen richt awa tae fix or stop serious trouble, wi a quicker approval tae match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Gettin the computer tae dae a repeated job by itsel, sae it's quicker an duin the same wey ilka time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks an services that software rins on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describin yer servers an settins in files kept wi the code, sae they can be rebiggit exactly the same wey ilka time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Rentin computers, storage an services frae a big provider ower the internet, instead o ownin the machines yersel.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents oot computin ower the internet, sic as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Whaur yer app or wabsite lives an rins sae fowk can reach it, usually rentit frae a company."},{"id":"domain","g":"change","word":"Domain name","text":"The web address fowk type, like example.com. Ye rent it by the year, sae it maun be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet's address beuk, that turns a name like example.com intae the address o the richt computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package haudin an app an aathin it needs, sae it rins the same on ony computer. Docker is the best kent tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer rinnin inside a real ane, sae ae big machine can act as mony.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Rinnin code wioot lookin efter ony servers yersel: the provider rins it whan needit an ye pey for whit ye uise."},{"id":"lb","g":"change","word":"Load balancer","text":"Somethin that spreids visitors across a wheen servers, sae nae single ane gets owerwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A haundy store o recent results kept close by, sae the same thing disnae hae tae be fetched or warked oot again. Clearin it can fix pages that look oot o date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A warldwide set o servers haudin copies o yer pages an pictures near yer visitors, sae they load quick.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Muivin data or systems frae an auld setup tae a new ane, or carefully chyngin hou a database is laid oot.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Service","text":"Somethin ye biggit that fowk rely on, like a website or an app, lookit efter sae it keeps wirkin. Tick “This project is a service” an say whit it offers, wha uises it an wha's on call.","also":["services"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"Hou muckle o the time a service is warkin, usually as a percentage. 99.9% still lets aboot 43 meenits doun a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, ilka few minutes, that yer service still answers. If it fails a wheen o times in a row, AI-gile opens an incident caird by itsel.","also":["uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is wirkin (green, orange or red) wi the latest update, sae the fowk that uise it can check insteid o speirin.","also":["status pages"]},{"id":"desk","g":"run","word":"Service desk","text":"Whaur questions an reports fae the fowk uisin yer service come in. AI-gile sorts ilka ane intae a request, an incident or an idea, an says sae when it looks like somethin awready reportit.","also":["service desks","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Service request","text":"Somebody askin fer somethin ordinar, like a new accoont or a wee bit help, raither than reportin that somethin's broke. It waits its turn; an incident gangs first.","also":["service requests"]},{"id":"incident","g":"run","word":"Incident","text":"Somethin that's broken or no warkin properly for the fowk uisin it richt noo, like the wabsite bein doun or gey slaw. A 🔥 incident caird jumps the queue: gettin it warkin again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A muckle incident: lots o fowk hit, or siller or data at risk. Ae button pits ilka team on it (swarm), wauks whaever's on call an asks fer a status update ilka 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Bein the ane that answers when somethin breks, even at nicht. Ilka service has an on-call team member that's waukit first fer its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How lang a caird may wait fer a first answer, for example an oor fer an incident. Efter that it gets a red clock, sae nocht is quietly forgot. Cried a response target an aw.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back efter an incident: whit happened, whit helped an whit tae chynge, wi'oot blamin onybody. An incident cannae be closed wi'oot ane.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause ahint ane or mair incidents. A 🧩 problem caird gethers incidents that keep comin back, sae the cause is fund an fixed fer guid.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason somethin broke, no jist whit ye saw gaun wrang. Fix the root cause an the incident stops comin back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A wey tae keep things wirkin till the real fix is ready, like restertin somethin when it gets stuck. It's written on the problem caird sae naebody has tae wark it oot again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whase cause is unnerstuid but isnae fixed yet, usually wi a workaround written doun. 🧩 Known errors lists them, sae aabody uises the workaround instead o diggin again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions fer fixin a kent kind o bother, sae it's duin the same wey, quick, ilka time. Efter a muckle incident the team can propose ane fer ye tae OK.","also":["runbooks"]},{"id":"ci","g":"run","word":"Configuration item","text":"Ae thing yer service depends on, like a server, a domain, a certificate, a key or a supplier. 🗂️ Configuration items lists them fer ilka service, sae ye can see whit an incident affects an whit needs renewin or a backup.","also":["configuration items"]},{"id":"expiry","g":"run","word":"Expiry date","text":"The date somethin stops warkin unless it's renewed, like a wabsite's security certificate or its web address. AI-gile watches thae dates an maks ae caird tae renew ilka ane 30 days afore, sae nocht stops by surprise.","also":["expiry dates","expiry","expiry watch"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy o yer data fae afore, tae faw back on if somethin's lost or damaged. AI-gile maks a backup o yer boards ilka day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Pittin data back fae a backup. A backup only really coonts aince ye ken it can be restored, sae it's worth tryin noo an again.","also":["restored"]},{"id":"svcreview","g":"run","word":"Service review","text":"A look back at ae month o a service: incidents opened an fixed, hoo quick fowk got an answer, uptime an tokens uised. The Monthly review shows it fer ilka service.","also":["service reviews","monthly review","monthly reviews"]},{"id":"accessreview","g":"run","word":"Access review","text":"Checkin ilka 90 days wha can still get in: share links, friends' roles an saved passwirds an keys. Ye keep or remove ilka ane, sae auld access disnae linger.","also":["access reviews"]},{"id":"improvements","g":"run","word":"Improvement list","text":"Awthing the team decidit tae get better at, in ae place: retro suggestions, review actions an problem fixes, ilka ane wi its status. Find it unner 📈 Improvements.","also":["improvement lists","improvements"]},{"id":"tokencap","g":"run","word":"Token cap","text":"A monthly limit on the tokens a service’s agents can uise. At 80% ye get a warnin; at 100% their backgrund wark waits till next month or till ye raise the cap.","also":["token caps"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Aathin involved in keepin a service uisefu an warkin for the fowk that rely on it, day efter day."},{"id":"itil","g":"run","word":"ITIL","text":"A widely uised guide tae guid service management, coverin things like incidents, problems an chynges. The name aince stuid for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Rinnin technology as a service for fowk, wi clear weys tae handle requests, incidents, chynges an improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service somebody else rins an looks efter for ye, unner an agreement aboot hou weel it maun wark.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The body that answers for a service as a hail: hou weel it warks, whit it costs an hou it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise tae customers aboot hou weel a service'll wark, like “up 99.9% o the time” or “answered inside an oor”, aften wi siller back if it's broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team's ain target for hou weel a service should wark ower a period, usually set a bit stricter than the SLA tae be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement ye check agin a target, like the share o visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether fowk can uise a service whan they need it, aften measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time whan a service isnae warkin or is switched aff, plannit or no.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The wee amoont o failure yer reliability target allous. While some is left ye can tak risks wi chynges; aince it's uised up, ye slaw doun.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time whan a service is doun or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Warkin, but badly: slaw, or wi some pairts no warkin.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watchin a service automatically aa the time, sae problems are spottit, ideally afore users notice."},{"id":"observability","g":"run","word":"Observability","text":"Hou weel ye can tell whit's gaun on inside a system frae the ootside, uisin its logs, nummers an traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A rinnin diary a program keeps o whit it's daein, uised tae wark oot whit gaed wrang.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record o hou ae request traivels throu the different pairts o a system, step by step, shawin whaur it slawed doun.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"Hou lang somethin taks tae answer, like the wait atween clickin an the page appearin."},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that somethin needs attention, like the wabsite no answerin.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"Whan there's sae mony alerts that fowk stert ignorin them, includin the important anes.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen shawin the maist important nummers an statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently ringin or wakkin the on-call body aboot a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringin in somebody wi mair skill or authority whan an issue cannae be sortit at the current level, or no fast eneuch.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sortin incomin issues by hou urgent an important they are, sae the warst gets haunled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"Hou muckle somethin affects fowk: hou mony, an hou badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"Hou quick somethin needs deelt wi. Impact an urgency thegither set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for hou urgent an issue is. P1 is the maist serious an needs action straucht awa.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list o requests an incidents waitin tae be pickit up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line an second line","text":"Levels o support: first line taks the cry an fixes simple things; second line has deeper skills for harder anes. Some caa them tier 1 an tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The ae body that leads the response tae an incident, sae aabody kens wha decides an wha daes whit.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"Hou lang it taks afore somebody first taks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"Hou lang it taks tae fully sort oot a request or incident, frae report tae fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, hou lang it taks tae get a service warkin again efter it breks. MTTR can mean slichtly different things, sae say whit ye measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, hou lang a service rins afore somethin breks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list o aa yer configuration items an hou they connect, sae ye can see whit depends on whit.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Onythin o value ye own or pey for tae rin the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Makkin shair there'll be eneuch computer pooer, storage an fowk for whit's comin.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Copin wi mair users by giein a machine mair pooer (scaling up) or addin mair machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keepin the important things gaun whan somethin big gaes wrang, like losin an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan an tools for gettin a service back efter somethin serious, like losin a hail data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The langest a service can be doun efter a disaster afore it maun be warkin again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"Hou muckle recent data ye could afford tae lose, measured in time. An RPO o ae oor means backups at least ilka oor.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Haein spares ready, like a second server, sae ae failure disnae stop the service."},{"id":"failover","g":"run","word":"Failover","text":"Switchin ower tae a spare system by itsel whan the usual ane fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"Ae pairt that taks aathin doun wi it whan it breks, cause there's nae spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A plannit time whan a service micht be pauset or slaw for upkeep, annooncet tae users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passin wark, knawledge an responsibility tae anither body or team, sae nocht gets drappit.","also":["handovers"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection o help airticles an answers, for users an for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score frae users sayin hou happy they were, aften speired efter a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An ootside company ye rely on, like yer hostin provider. Caad a vendor or third party an aa.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switchin a service aff for guid, safely: tellin its users, dealin wi its data an access, an stoppin its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"Whan a product stops gettin updates or support frae its makker, sae it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protectin systems an data frae bein broken intae, stown or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checkin wha somebody is, usually wi a passwird or a code. Aften shortened tae authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checkin whit somebody's allooed tae dae aince ye ken wha they are. Aften shortened tae authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Loggin in wi twa or mair proofs, like a passwird plus a code on yer phone. Caad two-factor (2FA) an aa.","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Loggin in aince tae get intae mony systems, like uisin yer wark accoont aawhaur.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strang passwirds an minds them for ye.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A passwird, key or ither private code a program uises tae get intae somethin. It maunna iver be shared or written intae the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program uise anither service's API, an shaws wha's uisin (an peyin for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program's allooed in, sae it disnae need yer passwird ilka time. No the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scramblin information sae only somebody wi the richt key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure wey web pages traivel, shawn by the padlock in yer browser, sae naebody atween can read or chynge them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID caird that lets a wabsite prove wha it is an uise HTTPS. It expires, sae it maun be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for wha can see or chynge whit.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giein ilka body or program only the access they truly need, for only as lang as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giein access by role, like viewer or editor, raither than body by body.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that somebody could uise tae brek in or cause hairm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers ken aboot afore the makkers hae haen ony time tae fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Hairmfu software, like viruses, made tae damage, spy or steal."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up yer files an demands siller tae unlock them. Guid backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try tae trick ye intae giein awa passwirds or siller, or openin somethin hairmfu.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Trickin fowk, raither than computers, intae giein access, like a fake cry frae “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guaird that decides whilk network traffic may come in or gae oot.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scramblit link ower the internet, aften uised tae reach wark systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Floodin a service wi sae muckle fake traffic that real fowk cannae uise it. DDoS means it comes frae mony computers at aince.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hirin friendly experts tae try tae brek in, sae weaknesses are fund afore real attackers fin them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A carefu check o hou weel somethin's protectit, agin a list o guid practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinkin throu wha micht attack somethin, hou, an whit ye wad dae tae stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"Whan private information gets oot tae fowk that shouldnae hae it, or is loast or chynged wioot permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Ony information aboot a body that can be identifiet, like a name, email address or location. Caad PII an aa.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its ain version): collect only whit ye need, keep it safe, an let fowk see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Lookin efter personal data properly an within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page sayin whit personal data ye collect, why, an whit ye dae wi it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A body's clear, free aye tae their data bein uised in a pairticular wey. They can tak it back at ony time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A wee file a wabsite saves in yer browser tae mind things, like bein loggit in. Some need yer consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collectin an keepin only the personal data ye really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"Hou lang data is kept afore it's deleted. Keepin it nae langer than needit is safer an aften the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Chyngin data sae naebody can reasonably be identifiet frae it ony mair.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swappin names an ither details for codes, wi a key kept apairt tae link them back. It's still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract sayin hou a supplier can haunle personal data on yer behauf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A carefu look, afore ye stert, at hou a plan tae uise personal data could affect fowk an hou tae lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record o wha did whit an whan, sae actions can be checked efter.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Follaein the laws, rules an staundards that apply tae ye, an bein able tae shaw that ye dae.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A weel kent international staundard for managin information security. Companies can be certifiet agin it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checkit by ootside auditors, shawin a company looks efter customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"An AI that warks on a task by itsel: reads the code, maks chynges, rins checks an reports back. Its wark still gets checkit.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"The wee pieces o text an AI reads an writes, aboot three quarters o a wird ilk. AI uise is coontit in tokens, sae fewer tokens leave mair o yer plan.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"A wee command that rins by itsel at a set meenit, for example whan an AI session stairts, sae the team hears yer comments.","also":["hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that dae things we usually think need a body, like writin, answerin questions or recognisin pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A wey o makkin computers lairn patterns frae lots o examples, instead o giein them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” o an AI system, biggit by lairnin frae huge nummers o examples. Models differ in skill, speed an price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amoonts o text, sae it can read an write leid.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, raither than only sortin or spottin them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program ye talk wi in everyday leid, by typin or speakin.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Whit ye gie an AI: yer question or instructions, plus onythin ye haund it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill o writin prompts that get reliable, uisefu results."},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets afore the conversation stairts, settin its role an rules. They weigh mair than whit ye type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Aathin the AI can see while it warks: the instructions, yer messages, files it has read an earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"Hou muckle an AI can keep in mind at aince, measured in tokens. Ayont that, aulder pairts get drappit or summarisit.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"Ae warkin blether wi an AI, frae stert tae feenish. A new session stairts wi a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps atween sessions, sae it minds yer preferences an past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"Whan an AI says somethin that soonds shair o itsel but is made up or wrang. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teachin a model by shawin it huge nummers o examples, afore onybody uises it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model lairnt frae. Its knawledge stops at the date that data wis collectit.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI's built-in knawledge ends. It winnae ken aboot later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra trainin o an existin model on yer ain examples, tae mak it better at ae particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually bein uised tae answer somethin, raither than bein trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI bein able tae dae things, no jist talk: rin commands, read files or seirch the web, throu tools the app gies it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hauns a smaaer job tae, an gets the result back frae.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"A wheen AIs warkin thegither on ae bit o wark, ilk wi its ain pairt, like a wee team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"Hou muckle an AI may dae on its ain afore it has tae spier at a body.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keepin a body involved tae check or approve whit the AI daes at key pynts. In AI-gile that's you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits an checks that keep an AI's actions safe, like needin approval afore onythin gaes live. They lower the risk o mistaks, but dinnae rule them oot.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Lettin an AI look things up in yer ain documents afore it answers, sae its answers rest on yer facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turnin text intae a list o nummers that catches its meanin, sae a computer can fin things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database biggit tae seirch thae lists o nummers (embeddings), tae fin material wi a similar meanin.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common wey tae plug tools an data sources intae AI apps, sae an AI can uise them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A settin for hou adventurous an AI's answers are. Laich gies steadier, mair predictable answers; heich gies mair varied anes. Neither maks it aye richt.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able tae wark wi mair than ae kind o information, sic as text, pictures an soond.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A plannit test o hou weel an AI daes on chosen examples, sae ye can compare models or prompts.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Bias","text":"Whan an AI (or a body) leans unfairly ae wey, aften cause o whit it lairnt frae.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Uisin AI fairly, safely an honestly, wi fowk still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick whaur hidden instructions in a web page or file try tae mak an AI dae somethin its user didnae spier for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on hou mony requests ye may send tae a service in a set time. Gae ower it an ye hae tae wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"Hou muckle AI wark yer plan allous in a period, efter whilk it pauses or costs mair.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Biggin software maistly by describin whit ye want tae an AI an lettin it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amoont o siller set aside for somethin.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at whit somethin'll cost afore ye stert.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"Whit ye get back compared wi whit ye pit in. If it's positive, it wis worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Aathin somethin really costs ower its hail life, no jist the price tae buy it: rinnin, support, upgrades an finally retirin it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx an OpEx","text":"CapEx is siller spent up front on things ye keep; OpEx is ongaun spendin, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Peyin regularly, usually monthly or yearly, tae keep uisin somethin.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software ye uise online an pey for by subscription, while the makker rins it for ye.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Peyin only for whit ye uise, like cloud computin or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Uise abune whit yer plan includes, that can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message whan spendin or uise reaches a level ye chose. It warns ye, but disnae aye stop further chairges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level o a peyed service, wi limits. Haundy for stertin oot.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, ilk wi its ain price an limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for hou ye may uise, copy, chynge or share somethin somebody else made, sic as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whase code onybody can read, uise an aften chynge for free, unner the rules o its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come wi open source code. Some let ye dae near-haund onythin (like MIT); some ask ye tae share yer chynges an aa (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company an no free tae copy or chynge. The opposite o open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal richt o a creator tae control copies o their wark, includin code an writin.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas an creations the law treats as owned, like code, designs, names an logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules ye agree tae whan ye uise a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement atween twa sides that the law'll back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document settin oot exactly whit wark'll be duin, by whan an for hou muckle.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the hail job, hooiver lang it taks.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time an materials","text":"Peyin for the oors really warked an the things really uised, raither than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill askin for peyment for wark duin or guids supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"Whan muivin awa frae a supplier is sae hard or costly that ye're stuck wi them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process o choosin an buyin frae suppliers."},{"id":"servicecredit","g":"money","word":"Service credit","text":"Siller back or a discoont ye get whan a supplier misses its SLA.","also":["service credits"]}]}};
